  ('el-sabor-nuevo', 'El Sabor Nuevo', 'el-sabor-nuevo', 'dallas', 'Pleasant Grove', 'mexican', 'New neighborhood taqueria', 'Fresh salsas and weekend carnitas. Joining GorditoPass soon.', 'Daily 10am–9pm', 'Pleasant Grove, Dallas, TX', 32.73, -96.68, '🌶️', '#d00000', true, false, true, 'seed'),
  ('food-factory', 'IM Food Factory', 'im-food-factory', 'tulsa', 'East Tulsa', 'american', 'Burgers and The Cure Food, on South Mingo', 'Food Factory Burgers and The Cure Food share the counter at 6217 S Mingo Rd. Dinner is Tuesday–Sunday 5pm–10:30pm, with lunch Tuesday–Saturday 10am–2pm. Phone 539-766-0614.', 'Tue–Sat 10am–2pm and 5pm–10:30pm; Sun 5pm–10:30pm; Mon closed', '6217 S Mingo Rd, Tulsa, OK 74133', 36.073, -95.8685, '🍔', '#2a9d8f', true, false, true, 'seed'),
  ('alpha-grill', 'Alpha Grill BBQ', 'alpha-grill-bbq', 'tulsa', 'Southern Hills', 'bbq', 'Slow-smoked barbecue on South Lewis', 'Alpha Grill BBQ serves smoked brisket, ribs, pulled pork, and scratch-made sides at 6670 S Lewis Ave #102. Open Wednesday–Sunday 11am–9pm. Phone (918) 621-8788.', 'Wed–Sun 11am–9pm; Mon–Tue closed', '6670 S Lewis Ave #102, Tulsa, OK 74136', 36.0660755, -95.958573, '🍖', '#b45309', true, false, true, 'seed'),
  ('just-winging', 'Brothers Just Wingin’ It', 'brothers-just-wingin-it', 'tulsa', 'East Tulsa', 'wings', 'Scratch-made wings from the family truck', 'Brothers Just Wingin’ It (also called Mr. & Mrs. Just Wingin’ It) is a Tulsa wing truck. A listed stop is 8601 S Mingo Rd. Yelp hours: Wed 12–7, Thu 2–8, Fri 3–9, Sat 12–8. Phone (918) 282-9339. The truck also posts weekly locations.', 'Wed 12pm–7pm; Thu 2pm–8pm; Fri 3pm–9pm; Sat 12pm–8pm', '8601 S Mingo Rd, Tulsa, OK 74133', 36.038, -95.8685, '🍗', '#e85d04', true, false, true, 'seed'),
  ('prossimos', 'Prossimo Ristorante', 'prossimo-ristorante', 'tulsa', 'Cherry Street', 'italian', 'Amalfi Coast pasta on Cherry Street', 'Prossimo serves light, artful pasta with seafood and vegetables at 1550 E 15th St. Hours: Mon–Thu 11am–10pm, Fri 11am–11pm, Sat 10am–11pm, Sun 10am–10pm. Phone (918) 271-5096.', 'Mon–Thu 11am–10pm; Fri 11am–11pm; Sat 10am–11pm; Sun 10am–10pm', '1550 E 15th St, Tulsa, OK 74120', 36.1405463, -95.970341, '🍝', '#457b9d', true, false, true, 'seed'),
  ('tacos-x-mezcal', 'Tacos x Mezcal', 'tacos-x-mezcal', 'tulsa', 'SoBo', 'mexican', 'Nayarit-style street tacos and agave', 'Tacos x Mezcal is at 39 E 18th St in the SoBo district. Tuesday–Wednesday 5pm–10pm, Thursday–Saturday 11am–10pm, Sunday 11am–9pm, Monday closed. Phone (918) 764-8666.', 'Tue–Wed 5pm–10pm; Thu–Sat 11am–10pm; Sun 11am–9pm; Mon closed', '39 E 18th St, Tulsa, OK 74119', 36.136146, -95.985479, '🌮', '#c1121f', true, false, true, 'seed'),
  ('kremee', 'Kremee Taiyaki and Ice Cream', 'kremee', 'tulsa', 'East Tulsa', 'other', 'Soft serve, milkshakes, and taiyaki', 'Kremee serves soft-serve, milkshakes, and taiyaki at 8316 E 61st St, Suite 106. Open Monday and Wednesday–Thursday 12pm–9pm, Friday–Saturday 12pm–10pm, Sunday 12pm–9pm. Tuesday closed. Phone (918) 749-1111.', 'Mon, Wed–Thu, Sun 12pm–9pm; Fri–Sat 12pm–10pm; Tue closed', '8316 E 61st St, Ste 106, Tulsa, OK 74133', 36.074783, -95.883771, '🍦', '#f4a261', true, false, true, 'seed'),
  ('boujee-delights', 'Boujee Delights', 'boujee-delights', 'tulsa', 'Skiatook', 'other', 'Shaved ice, Dole Whip, and loaded teas', 'Boujee Delights is a snack shop in the Tulsa area at 214 S Locust St, Skiatook. Shaved ice, Dole Whip, ice cream, smoothies, and loaded teas. Phone (918) 313-3785. Hours posted on Yelp: Mon–Thu and Sun 12pm–8:30pm, Fri 12pm–9pm, Sat 2pm–9pm.', 'Mon–Thu 12pm–8:30pm; Fri 12pm–9pm; Sat 2pm–9pm; Sun 12pm–8:30pm', '214 S Locust St, Skiatook, OK 74070', 36.3684042, -96.0055555, '🍧', '#db2777', true, false, true, 'seed'),
  ('coffee-grinder', 'The Coffee Grinder', 'the-coffee-grinder', 'tulsa', 'Sheridan', 'american', 'Coffee and pastries on South Sheridan', 'The Coffee Grinder is a café at 5233 S Sheridan Rd, Tulsa. Fresh coffee and pastries. Confirm today’s hours at the shop before you go.', 'See the café for today’s hours', '5233 S Sheridan Rd, Tulsa, OK 74145', 36.087, -95.9045, '☕', '#6f4e37', true, false, true, 'seed'),
  ('andolinis', 'Andolini’s Pizzeria', 'andolinis-pizzeria', 'tulsa', 'Cherry Street', 'pizza', 'Cherry Street pies next door to Prossimo', 'Andolini’s Pizzeria on Cherry Street is at 1552 E 15th St, Tulsa. Neighborhood pizzas and a full pie menu. Phone is listed with the restaurant.', 'Daily 11am–11pm', '1552 E 15th St, Tulsa, OK 74120', 36.1404253, -95.9697367, '🍕', '#c1121f', true, false, true, 'seed'),
  ('casa-arepa', 'El Arepaso Venezuelan Cafe', 'el-arepaso', 'tulsa', 'Yale', 'latin', 'Venezuelan arepas, empanadas, and coffee', 'El Arepaso Venezuelan Cafe is at 8036 S Yale Ave, Tulsa. Phone (918) 430-3136. A recent public listing shows Sunday 10am–6pm and Monday–Saturday 11am–8pm.', 'Sun 10am–6pm; Mon–Sat 11am–8pm', '8036 S Yale Ave, Tulsa, OK 74136', 36.0470255, -95.9236039, '🫓', '#f4a261', true, false, true, 'seed'),
  ('mi-tierra', 'Mi Tierra Cocina Mexicana', 'mi-tierra-cocina-mexicana', 'tulsa', 'KingsPoint Village', 'mexican', 'Family-style Mexican kitchen on South Yale', 'Mi Tierra Cocina Mexicana’s KingsPoint Village location is at 6030 S Yale Ave, Tulsa. The family also has kitchens at 9521 Riverside Parkway and in Glenpool. Tulsa World listed hours as 11am–10pm daily. Phone 539-215-6974.', 'Daily 11am–10pm', '6030 S Yale Ave, Tulsa, OK 74136', 36.0735, -95.9223, '🌮', '#e85d04', true, false, true, 'seed')
